# Verify flood fill works for Demo1 (13x18, values 0,4,6)
import json
import os
from collections import deque

base_dir = "/home/ubuntu/runs/paper/qwen-hpl-u1-turns/play/users/u000/system/state/workspace/programs"

with open(os.path.join(base_dir, "task-7f822ef5.json"), "r") as f:
    demos = json.load(f)

def flood_fill(grid, seed_value):
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    seeds = [(r, c) for r in range(n) for c in range(m) if grid[r][c] == seed_value]
    visited = set(seeds)
    queue = deque(seeds)

    working = [row[:] for row in grid]

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                if (nr, nc) not in visited and grid[nr][nc] == 0:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
                    working[nr][nc] = seed_value

    return working

for demo in demos:
    if "input" in demo and "output" in demo:
        inp = demo["input"]
        out = demo["output"]
        seed_val = list(set(inp[0]))[1]  # 0 is background, pick one other

        # For Demo1 (13x18, values 0,4,6), seed is 4
        # For Demo2 (19x19, values 0,2,5), seed is 2
        if seed_val == 4:
            result = flood_fill(inp, 4)
        elif seed_val == 2:
            result = flood_fill(inp, 2)
        else:
            result = flood_fill(inp, seed_val)

        match = result == out
        print(f"Demo {demo.keys()[0]}: 13x{len(inp[0])} values {{{set(inp[0])}}}, seed={seed_val}, matches={match}")
        if not match:
            print("  First mismatch:")
            for r in range(min(len(result), len(out))):
                for c in range(min(len(result[0]), len(out[0]))):
                    if result[r][c] != out[r][c]:
                        print(f"    ({r},{c}): got {result[r][c]}, expected {out[r][c]}")

